CREATE TABLE ATS_Etapas (ID_Etapa CHAR(36) PRIMARY KEY, ID_Vagas CHAR(36) NOT NULL, Nome VARCHAR(150) NOT NULL, Ordem INT NOT NULL, Ativa BOOLEAN NOT NULL DEFAULT 1);
CREATE TABLE ATS_Cards (ID_Candidaturas CHAR(36) PRIMARY KEY, ID_Etapa CHAR(36) NOT NULL, ID_Responsavel CHAR(36) NULL, Prazo DATE NULL, EntradaEm DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, Ordem INT NOT NULL DEFAULT 0, Estado VARCHAR(20) NOT NULL DEFAULT 'ativo', Notas TEXT NULL, Motivo TEXT NULL, Versao INT NOT NULL DEFAULT 1);
CREATE TABLE ATS_Eventos (ID_Evento CHAR(36) PRIMARY KEY, ID_Candidaturas CHAR(36) NOT NULL, ID_Usuarios CHAR(36) NOT NULL, Acao VARCHAR(50) NOT NULL, Sequencia INT NOT NULL, Antes TEXT NULL, Depois TEXT NULL, CriadoEm DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ATS_Modelos (ID_Modelo CHAR(36) PRIMARY KEY, ID_Etapa CHAR(36) NOT NULL, Nome VARCHAR(150) NOT NULL, Cego BOOLEAN NOT NULL DEFAULT 1, Criterios TEXT NOT NULL, CriadoEm DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ATS_Avaliacoes (ID_Avaliacao CHAR(36) PRIMARY KEY, ID_Modelo CHAR(36) NOT NULL, ID_Candidaturas CHAR(36) NOT NULL, ID_Usuarios CHAR(36) NOT NULL, Notas TEXT NOT NULL, Comentario TEXT NULL, Parecer TEXT NOT NULL, Recomendacao VARCHAR(20) NOT NULL, Media DECIMAL(8,4) NULL, CriadoEm DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(ID_Modelo,ID_Candidaturas,ID_Usuarios));
CREATE TABLE ATS_Consentimentos (ID_Candidatos CHAR(36) NOT NULL, ID_Empresas CHAR(36) NOT NULL, Autorizado BOOLEAN NOT NULL, AtualizadoEm DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(ID_Candidatos,ID_Empresas));
CREATE TABLE ATS_Pools (ID_Pool CHAR(36) PRIMARY KEY, ID_Empresas CHAR(36) NOT NULL, Nome VARCHAR(150) NOT NULL, Ativo BOOLEAN NOT NULL DEFAULT 1);
CREATE TABLE ATS_Membros (ID_Pool CHAR(36) NOT NULL, ID_Candidatos CHAR(36) NOT NULL, Tags TEXT NOT NULL, Favorito BOOLEAN NOT NULL DEFAULT 0, Notas TEXT NULL, Ativo BOOLEAN NOT NULL DEFAULT 1, CriadoEm DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(ID_Pool,ID_Candidatos));
CREATE TABLE ATS_Convites (ID_Convite CHAR(36) PRIMARY KEY, ID_Candidatos CHAR(36) NOT NULL, ID_Vagas CHAR(36) NOT NULL, ID_Usuarios CHAR(36) NOT NULL, CriadoEm DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(ID_Candidatos,ID_Vagas));